#!/usr/bin/env python3
"""Multi-API LLM benchmark harness with streaming TTFT measurement."""
import argparse
import concurrent.futures
import json
import os
import sys
import time
import uuid
from datetime import datetime, timezone
from urllib import request as urlrequest
from urllib.error import HTTPError, URLError

PROMPT = "Reply with exactly one sentence about the color blue."


def build_request(model_cfg):
    api_type = model_cfg["api_type"]
    base_url = model_cfg["base_url"].rstrip("/")
    body = {"model": model_cfg["id"], "stream": True}
    if "temperature" in model_cfg:
        body["temperature"] = model_cfg["temperature"]
    if "max_tokens" in model_cfg:
        body["max_tokens"] = model_cfg["max_tokens"]

    if api_type == "chat_completions":
        url = f"{base_url}/v1/chat/completions"
        body["messages"] = [{"role": "user", "content": PROMPT}]
    elif api_type == "responses":
        url = f"{base_url}/v1/responses"
        body["input"] = PROMPT
    else:
        raise ValueError(f"Unknown api_type: {api_type}")

    headers = {
        "Content-Type": "application/json",
        "Accept": "text/event-stream",
    }
    key_env = model_cfg.get("api_key_env")
    if key_env:
        api_key = os.environ.get(key_env)
        if api_key:
            headers["Authorization"] = f"Bearer {api_key}"
    return url, body, headers


def extract_delta(api_type, payload):
    """Extract text delta from a parsed SSE JSON payload."""
    try:
        if api_type == "chat_completions":
            choices = payload.get("choices") or []
            if not choices:
                return ""
            delta = choices[0].get("delta") or {}
            return delta.get("content") or ""
        elif api_type == "responses":
            ptype = payload.get("type", "")
            if ptype == "content_block_delta":
                delta = payload.get("delta") or {}
                return delta.get("text") or ""
            # Be lenient - support other delta shapes
            if "delta" in payload:
                d = payload["delta"]
                if isinstance(d, dict):
                    return d.get("text") or d.get("content") or ""
                if isinstance(d, str):
                    return d
            return ""
    except Exception:
        return ""
    return ""


def benchmark_model(model_cfg, timeout):
    model_id = model_cfg.get("id", "<unknown>")
    api_type = model_cfg.get("api_type", "<unknown>")
    result = {
        "model_id": model_id,
        "api_type": api_type,
        "status": "error",
        "ttft_ms": None,
        "total_ms": None,
        "first_token": None,
        "full_response": None,
        "error": None,
    }

    try:
        url, body, headers = build_request(model_cfg)
    except Exception as e:
        result["error"] = f"config error: {e}"
        return result

    data = json.dumps(body).encode("utf-8")
    req = urlrequest.Request(url, data=data, headers=headers, method="POST")

    t_start = time.perf_counter()
    t_first = None
    chunks = []
    first_token = None

    try:
        with urlrequest.urlopen(req, timeout=timeout) as resp:
            for raw_line in resp:
                line = raw_line.decode("utf-8", errors="replace").rstrip("\r\n")
                if not line or not line.startswith("data:"):
                    continue
                data_str = line[5:].lstrip()
                if data_str == "[DONE]":
                    break
                try:
                    payload = json.loads(data_str)
                except json.JSONDecodeError:
                    continue
                delta = extract_delta(api_type, payload)
                if delta:
                    if t_first is None:
                        t_first = time.perf_counter()
                        first_token = delta
                    chunks.append(delta)
        t_end = time.perf_counter()
        result["total_ms"] = round((t_end - t_start) * 1000, 2)
        if t_first is not None:
            result["status"] = "ok"
            result["ttft_ms"] = round((t_first - t_start) * 1000, 2)
            result["first_token"] = first_token
            result["full_response"] = "".join(chunks)
        else:
            result["error"] = "no content delta received"
    except HTTPError as e:
        t_end = time.perf_counter()
        result["total_ms"] = round((t_end - t_start) * 1000, 2)
        try:
            body_text = e.read().decode("utf-8", errors="replace")[:500]
        except Exception:
            body_text = ""
        result["error"] = f"HTTP {e.code}: {e.reason} {body_text}".strip()
    except URLError as e:
        t_end = time.perf_counter()
        result["total_ms"] = round((t_end - t_start) * 1000, 2)
        result["error"] = f"URL error: {e.reason}"
    except TimeoutError:
        t_end = time.perf_counter()
        result["total_ms"] = round((t_end - t_start) * 1000, 2)
        result["error"] = f"timeout after {timeout}s"
    except Exception as e:
        t_end = time.perf_counter()
        result["total_ms"] = round((t_end - t_start) * 1000, 2)
        result["error"] = f"{type(e).__name__}: {e}"

    return result


def summarize(results):
    ok = [r for r in results if r["status"] == "ok"]
    errors = [r for r in results if r["status"] != "ok"]
    summary = {
        "total": len(results),
        "ok": len(ok),
        "errors": len(errors),
        "avg_ttft_ms": None,
        "fastest_model": None,
        "slowest_model": None,
    }
    if ok:
        ttfts = [r["ttft_ms"] for r in ok]
        summary["avg_ttft_ms"] = round(sum(ttfts) / len(ttfts), 2)
        fastest = min(ok, key=lambda r: r["ttft_ms"])
        slowest = max(ok, key=lambda r: r["ttft_ms"])
        summary["fastest_model"] = fastest["model_id"]
        summary["slowest_model"] = slowest["model_id"]
    return summary


def main():
    parser = argparse.ArgumentParser(description="Multi-API LLM benchmark harness")
    parser.add_argument("--config", required=True)
    parser.add_argument("--output", default="benchmark_results.json")
    parser.add_argument("--timeout", type=float, default=30)
    parser.add_argument("--workers", type=int, default=1)
    args = parser.parse_args()

    with open(args.config) as f:
        config = json.load(f)
    models = config.get("models", [])
    if not models:
        print("No models in config", file=sys.stderr)
        sys.exit(1)

    results = [None] * len(models)
    workers = max(1, args.workers)
    with concurrent.futures.ThreadPoolExecutor(max_workers=workers) as ex:
        future_to_idx = {
            ex.submit(benchmark_model, m, args.timeout): i
            for i, m in enumerate(models)
        }
        for fut in concurrent.futures.as_completed(future_to_idx):
            i = future_to_idx[fut]
            try:
                results[i] = fut.result()
            except Exception as e:
                results[i] = {
                    "model_id": models[i].get("id", "<unknown>"),
                    "api_type": models[i].get("api_type", "<unknown>"),
                    "status": "error",
                    "ttft_ms": None,
                    "total_ms": None,
                    "first_token": None,
                    "full_response": None,
                    "error": f"worker exception: {e}",
                }
            r = results[i]
            status = r["status"]
            if status == "ok":
                print(f"[ok]    {r['model_id']:30s} ttft={r['ttft_ms']}ms total={r['total_ms']}ms")
            else:
                print(f"[error] {r['model_id']:30s} {r['error']}")

    output = {
        "run_id": str(uuid.uuid4()),
        "timestamp": datetime.now(timezone.utc).isoformat(),
        "prompt": PROMPT,
        "results": results,
        "summary": summarize(results),
    }
    with open(args.output, "w") as f:
        json.dump(output, f, indent=2)
    print(f"\nWrote {args.output}")


if __name__ == "__main__":
    main()
